#!/usr/bin/env bash
# generated by make-theme.cjs — plate reaction for theme "ordnance"
set -euo pipefail
cd "$(dirname "$0")"
ffmpeg -y -v error -i final.mp4 -filter_complex "
  [0:v]scale=2560:1440:flags=lanczos,zoompan=
    z='1+0.045*exp(-9*(time-2.505))*between(time,2.505,2.505+0.6)':
    x='iw/2-(iw/zoom/2)+14*exp(-7*(time-2.505))*sin(2*PI*12*(time-2.505))*between(time,2.505,2.505+0.6)':
    y='ih/2-(ih/zoom/2)+10*exp(-7*(time-2.505))*cos(2*PI*15.72*(time-2.505))*between(time,2.505,2.505+0.6)':
    d=1:s=2560x1440:fps=25,scale=1280:720:flags=lanczos,noise=alls=6:allf=t+u[v]" \
  -map "[v]" -map 0:a -c:v libx264 -crf 14 -preset slow -profile:v high -c:a copy \
  final_fx.mp4
echo "[postfx] ordnance → final_fx.mp4"
